def retrieval_agent(query):
    # a specialist agent with its own tool: search
    return "Falcon plan costs twenty dollars per month. Includes ten projects."

def summarization_agent(text):
    # a specialist agent with its own tool: condensing text
    return text.split(".")[0] + "."

def reviewer_agent(summary):
    # reflection applied across agents, not just within one
    return len(summary) > 5

def coordinator(query):
    # the coordinator assigns work to each specialist
    raw_findings = retrieval_agent(query)
    summary = summarization_agent(raw_findings)  # one agent's output becomes the next agent's input
    if reviewer_agent(summary):
        return {"status": "approved", "summary": summary}
    return {"status": "rejected", "summary": None}

result = coordinator("What does the Falcon plan cost?")
print("Multi-agent coordination result:")
print(result)
